package main

// TierName returns the loyalty tier for a points total.
func TierName(points int) string {
	switch {
	case points >= 1000:
		return "platinum"
	case points >= 500:
		return "gold"
	case points >= 100:
		return "silver"
	default:
		return "bronze"
	}
}

