package main

import "testing"

func TestTierName(t *testing.T) {
	cases := map[int]string{
		0: "bronze", 99: "bronze",
		100: "silver", 499: "silver",
		500: "gold", 999: "gold",
		1000: "platinum", 5000: "platinum",
	}
	for points, want := range cases {
		if got := TierName(points); got != want {
			t.Errorf("TierName(%d) = %q, want %q", points, got, want)
		}
	}
}

