package main

var tierTable = []struct {
	min  int
	name string
}{
	{1000, "platinum"},
	{500, "gold"},
	{100, "silver"},
	{0, "bronze"},
}

// TierName returns the loyalty tier for a points total.
func TierName(points int) string {
	for _, tier := range tierTable {
		if points >= tier.min {
			return tier.name
		}
	}
	return "bronze"
}

